"""Read-only representation coverage for the operator application read model."""
from __future__ import annotations
from dataclasses import dataclass
from src.operator_app_store import CONTENT_VERIFIED, inspect_store_content,read_model_integrity_status
CATEGORIES=("snapshots","timeline","incidents","imports","read_model_identity_integrity")
@dataclass(frozen=True)
class EvidenceCoverage:
    schema_version:int; generated_as_of:str; coverage_status:str; expected_category_count:int; represented_category_count:int; missing_category_count:int; degraded_category_count:int; category_rows:tuple[dict,...]; blocker_reasons:tuple[str,...]
    def to_dict(self): return {"schema_version":self.schema_version,"generated_as_of":self.generated_as_of,"coverage_status":self.coverage_status,"expected_category_count":self.expected_category_count,"represented_category_count":self.represented_category_count,"missing_category_count":self.missing_category_count,"degraded_category_count":self.degraded_category_count,"category_rows":[dict(x) for x in self.category_rows],"blocker_reasons":list(self.blocker_reasons),"permits_automated_action":False,"live_ready":False,"unattended_ready":False}
def read_coverage(database,generated_as_of,expected_content_digest=None):
    counts=inspect_store_content(database); integrity=read_model_integrity_status(database,expected_content_digest=expected_content_digest); verified=integrity==CONTENT_VERIFIED; mapping={"snapshots":counts["snapshot_count"],"timeline":counts["event_count"],"incidents":counts["incident_count"],"imports":counts["import_batch_count"],"read_model_identity_integrity":1 if verified else 0}; rows=tuple({"category_code":k,"represented":v>0,"record_count":v,"latest_observed_at":counts.get("newest_"+({"snapshots":"snapshot_at","timeline":"event_at","incidents":"incident_at","imports":"imported_at"}.get(k,"snapshot_at"))),"freshness_class":"UNKNOWN_FAIL_CLOSED","integrity_status":integrity if k=="read_model_identity_integrity" else "NOT_APPLICABLE","identity_status":"UNKNOWN_FAIL_CLOSED","related_blocker_count":0,"source_types":[k],"detail_links":[],"blocker_reasons":[] if v>0 else ["CATEGORY_MISSING"]} for k,v in sorted(mapping.items())); represented=sum(x["represented"] for x in rows); missing=len(rows)-represented; status="COMPLETE_EVIDENCE_COVERAGE" if missing==0 else "PARTIAL_EVIDENCE_COVERAGE"; return EvidenceCoverage(1,generated_as_of,status,len(rows),represented,missing,0,rows,tuple("CATEGORY_MISSING" for x in rows if not x["represented"]))
